static public File allocateFile(File dir, String name) {
    if (dir == null || name == null) {
        throw new IllegalArgumentException("Directory and name must not be null");
    }
    // Remove query parameters
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Reject absolute paths
    if (new File(name).isAbsolute()) {
        throw new IllegalArgumentException("Absolute paths are not allowed");
    }
    // Build file
    File file = new File(dir, name);
    // Normalize and verify containment
    Path dirPath = dir.toPath().toAbsolutePath().normalize();
    Path filePath = file.toPath().toAbsolutePath().normalize();
    if (!filePath.startsWith(dirPath)) {
        throw new IllegalArgumentException("File path escapes the target directory");
    }
    // Resolve duplicate names
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
        filePath = file.toPath().toAbsolutePath().normalize();
        if (!filePath.startsWith(dirPath)) {
            throw new IllegalArgumentException("Generated file path escapes the target directory");
        }
    }
    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IOException("Failed to create parent directories");
    }
    return file;
}

