public class COSArray extends COSBase implements Iterable<COSBase>, COSUpdateInfo {

    /* --------------------------------------------------------------------- */
    /*  Data members                                                        */
    /* --------------------------------------------------------------------- */

    /** Holds the elements of this COSArray. */
    private final List<COSBase> objects = new ArrayList<>();

    /* --------------------------------------------------------------------- */
    /*  Constants                                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Maximum number of elements that may be converted to a float array.
     * This protects against denial‑of‑service attacks caused by maliciously
     * large arrays.
     */
    private static final int MAX_FLOAT_ARRAY_SIZE = 10_000;

    /* --------------------------------------------------------------------- */
    /*  Public API                                                          */
    /* --------------------------------------------------------------------- */

    /**
     * Converts the COSArray to an array of floats.
     *
     * <p>The original implementation blindly casted every element to {@link COSNumber},
     * which could lead to {@link ClassCastException} and, more importantly,
     * allowed an attacker to craft a PDF that contains a very large number of
     * elements, causing the method to consume excessive CPU time.</p>
     *
     * <p>This patched version:</p>
     * <ul>
     *   <li>Captures the size once to guard against concurrent modifications.</li>
     *   <li>Enforces a hard limit on the number of elements that can be processed.</li>
     *   <li>Verifies that each element is a {@link COSNumber} (or {@code null}) before
     *       conversion, throwing an exception for unexpected types.</li>
     *   <li>Handles {@code null} elements by treating them as {@code 0.0f}.</li>
     * </ul>
     *
     * @return a float array containing the numeric values of the COSArray.
     * @throws IllegalStateException if the array is too large or contains
     *         non‑numeric elements.
     */
    public float[] toFloatArray() {
        final int sz = size();

        if (sz > MAX_FLOAT_ARRAY_SIZE) {
            throw new IllegalStateException(
                "COSArray too large (" + sz + ") to convert to float array");
        }

        final float[] retval = new float[sz];

        for (int i = 0; i < sz; i++) {
            final COSBase obj = getObject(i);

            if (obj instanceof COSNumber) {
                retval[i] = ((COSNumber) obj).floatValue();
            } else if (obj == null) {
                // Treat COSNull as zero – this mirrors the behaviour of many PDF libraries.
                retval[i] = 0.0f;
