     * @param toVersion   the target version string
     * @return a negative integer if {@code fromVersion} is less than {@code toVersion},
     *         zero if they are equal, or a positive integer if {@code fromVersion}
     *         is greater than {@code toVersion}
     * @throws IllegalArgumentException if either argument is invalid
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        // Validate non‑null
        if (fromVersion == null || toVersion == null) {
            throw new IllegalArgumentException("Version strings must not be null");
        }

        // Split and validate component count
        String[] fromParts = fromVersion.split("\\.");
        String[] toParts = toVersion.split("\\.");

        if (fromParts.length != 3 || toParts.length != 3) {
            throw new IllegalArgumentException(
                "Version strings must have the form 'major.minor.patch'");
        }

        // Parse each component safely
        int fromMajor = parseComponent(fromParts[0], "major", fromVersion);
        int fromMinor = parseComponent(fromParts[1], "minor", fromVersion);
        int fromPatch = parseComponent(fromParts[2], "patch", fromVersion);

        int toMajor = parseComponent(toParts[0], "major", toVersion);
        int toMinor = parseComponent(toParts[1], "minor", toVersion);
        int toPatch = parseComponent(toParts[2], "patch", toVersion);

        // Compare major, then minor, then patch
        int cmp = Integer.compare(fromMajor, toMajor);
        if (cmp != 0) {
            return cmp;
        }
        cmp = Integer.compare(fromMinor, toMinor);
        if (cmp != 0) {
            return cmp;
        }
        return Integer.compare(fromPatch, toPatch);
    }

    /**
     * Parses a single numeric component of a version string.
     *
     * @param part      the string component to parse
