     * @return the integer value of the component
     * @throws IllegalArgumentException if the component is not a valid integer
     */
    private static int parseComponent(String part, String label, String fullVer) {
        try {
            // Leading zeros are allowed; Integer.parseInt handles them correctly
            return Integer.parseInt(part);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                String.format("Invalid %s component '%s' in version '%s'", label, part, fullVer), e);
        }
    }

