public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods

    /**
     * Determines whether the current authenticated user is allowed to perform a self‑update
     * operation on the SCIM user identified by the request URL.
     *
     * <p>Security checks performed:</p>
     * <ul>
     *   <li>Authenticated user must exist and be authenticated.</li>
     *   <li>The authenticated user's username must match the username of the target SCIM user.</li>
     *   <li>All mutable attributes are compared using {@link Objects#equals(Object, Object)} to guard
     *       against {@code null} values.</li>
     *   <li>If the primary email is being changed, the new email must be verified before the change
     *       is accepted.  The actual verification workflow (e.g., sending a confirmation email)
     *       is delegated to an external service and is represented here by a placeholder method
     *       {@code verifyNewEmail(ScimUser)}.</li>
     * </ul>
