     * @return {@code true} if the operation is permitted, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Read and parse the request body
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            return false;
        }

        // 2. Resolve the target user ID from the request URL
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 3. Retrieve the current state of the user from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation to proceed (e.g., creation)
            return true;
        }

        // 4. Verify that the request is coming from the user themselves
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication == null || !authentication.isAuthenticated()) {
            return false;
        }
        String authenticatedUsername = authentication.getName();
        if (!Objects.equals(scimUserFromDb.getUserName(), authenticatedUsername)) {
            return false;
        }

        // 5. Compare all relevant fields, guarding against nulls
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            // If the email is changing, ensure the new address is verified
            if (!scimUserFromRequest.isVerified()) {
                // Trigger email verification workflow (implementation omitted)
                verifyNewEmail(scimUserFromRequest);
                return false; // Deny until verification completes
            }
        }

        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }

        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }

        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the operation is allowed
        return true;
    }

